alter table public.suppliers
  add column row_version bigint not null default 1 check (row_version > 0),
  add column last_change_request_id uuid,
  add column country_code text check (country_code is null or country_code ~ '^[A-Z]{2}$'),
  add column org_number_key text generated always as
    (nullif(upper(regexp_replace(normalize(btrim(org_number), NFKC), '[[:space:]-]+', '', 'g')), '')) stored;
create unique index suppliers_country_identity_uidx
  on public.suppliers(company_id, coalesce(country_code, ''), org_number_key)
  where org_number_key is not null;

alter table public.supplier_change_events add column request_id uuid;
create unique index supplier_change_events_request_uidx
  on public.supplier_change_events(company_id, supplier_id, request_id, change_type)
  where request_id is not null;

create or replace function lt_security.audit_supplier_mutation()
returns trigger language plpgsql security definer set search_path='' as $$
declare
  v_uid uuid := auth.uid();
  v_org text;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb;
  v_before_payment jsonb := '{}'::jsonb;
  v_after_payment jsonb;
begin
  if tg_op='DELETE' then raise exception 'SUPPLIER_ARCHIVE_REQUIRED'; end if;
  if tg_op='UPDATE' then
    if new.id is distinct from old.id or new.company_id is distinct from old.company_id then
      raise exception 'SUPPLIER_IDENTITY_IMMUTABLE';
    end if;
    if new.row_version is distinct from old.row_version+1 then
      raise exception 'SUPPLIER_VERSION_CONFLICT';
    end if;
  elsif new.row_version <> 1 then
    raise exception 'SUPPLIER_VERSION_CONFLICT';
  end if;
  if v_uid is not null then
    if not lt_security.request_has_aal2_personal_session() or not exists (
      select 1 from public.company_memberships m
      where m.company_id=new.company_id and m.auth_user_id=v_uid and m.role in ('admin','accountant')
    ) then raise exception 'ACCESS_DENIED'; end if;
  elsif current_setting('role',true) in ('anon','authenticated') then
    raise exception 'AUTH_REQUIRED';
  end if;
  -- A missing id is allowed for existing create clients; the server supplies it.
  -- Updates must always carry a fresh client request identity and exact revision.
  if tg_op='UPDATE' and (new.last_change_request_id is null or
      new.last_change_request_id is not distinct from old.last_change_request_id) then
    raise exception 'SUPPLIER_REQUEST_ID_REQUIRED';
  end if;
  if new.last_change_request_id is null then new.last_change_request_id:=gen_random_uuid(); end if;
  if v_uid is not null and exists (select 1 from public.supplier_change_events e
      where e.company_id=new.company_id and e.supplier_id=new.id and e.request_id=new.last_change_request_id) then
    raise exception 'SUPPLIER_REQUEST_ALREADY_APPLIED';
  end if;
  if char_length(btrim(new.name)) not between 1 and 160 or new.name ~ '[[:cntrl:]]'
     or char_length(btrim(new.supplier_number)) not between 1 and 40
     or new.supplier_number ~ '[[:cntrl:]]'
     or coalesce(char_length(new.org_number),0)>40 or coalesce(new.org_number,'') ~ '[[:cntrl:]]'
     or coalesce(char_length(new.email),0)>254 or coalesce(new.email,'') ~ '[[:cntrl:]]'
     or coalesce(char_length(new.bankgiro),0)>40 or coalesce(new.bankgiro,'') ~ '[[:cntrl:]]'
     or coalesce(char_length(new.plusgiro),0)>40 or coalesce(new.plusgiro,'') ~ '[[:cntrl:]]' then
    raise exception 'INVALID_SUPPLIER_INPUT';
  end if;
  v_org:=nullif(upper(regexp_replace(normalize(btrim(new.org_number),NFKC),'[[:space:]-]+','','g')),'');
