    -- Serialize identity decisions, including legacy rows without an explicit
    -- jurisdiction. Never silently merge those with a newly asserted country.
    perform pg_advisory_xact_lock(hashtextextended(new.company_id||':'||v_org,823));
    if exists(select 1 from public.suppliers s where s.company_id=new.company_id and s.id<>new.id
      and s.org_number_key=v_org and
      (s.country_code is null or new.country_code is null or s.country_code=new.country_code)) then
      raise exception 'SUPPLIER_IDENTITY_ALREADY_EXISTS';
    end if;
  end if;
