create or replace function lt_security.record_supplier_mutation()
returns trigger language plpgsql security definer set search_path='' as $$
declare
 v_uid uuid:=auth.uid();
 v_before jsonb:='{}'::jsonb;
 v_after jsonb;
 v_before_payment jsonb:='{}'::jsonb;
 v_after_payment jsonb;
begin
 -- Migration/seed/service provisioning without a personal actor is not falsely
 -- attributed to a human. Browser writes always have an authenticated actor.
 if v_uid is null then return new; end if;
 if not lt_security.request_has_aal2_personal_session() then raise exception 'AUTH_REQUIRED'; end if;
 if tg_op='UPDATE' then
   v_before:=jsonb_build_object('name',old.name,'supplierNumber',old.supplier_number,'orgNumber',old.org_number,
     'countryCode',old.country_code,'email',old.email,'defaultCostAccount',old.default_cost_account,
     'address',old.address_json,'archivedAt',old.archived_at,'rowVersion',old.row_version);
   v_before_payment:=jsonb_build_object('bankgiro',old.bankgiro,'plusgiro',old.plusgiro);
 end if;
 v_after:=jsonb_build_object('name',new.name,'supplierNumber',new.supplier_number,'orgNumber',new.org_number,
   'countryCode',new.country_code,'email',new.email,'defaultCostAccount',new.default_cost_account,
   'address',new.address_json,'archivedAt',new.archived_at,'rowVersion',new.row_version);
 v_after_payment:=jsonb_build_object('bankgiro',new.bankgiro,'plusgiro',new.plusgiro);
 if tg_op='INSERT' or (v_before-'rowVersion') is distinct from (v_after-'rowVersion') then
   insert into public.supplier_change_events(company_id,supplier_id,change_type,changed_by,before_json,after_json,request_id)
   values(new.company_id,new.id,'profile',v_uid,v_before,v_after,new.last_change_request_id);
 end if;
 if (tg_op='INSERT' and (new.bankgiro is not null or new.plusgiro is not null)) or
     (tg_op='UPDATE' and v_before_payment is distinct from v_after_payment) then
   insert into public.supplier_change_events(company_id,supplier_id,change_type,changed_by,before_json,after_json,request_id)
   values(new.company_id,new.id,'payment-details',v_uid,v_before_payment,v_after_payment,new.last_change_request_id);
 end if;
 return new;
end;
$$;
revoke all on function lt_security.record_supplier_mutation() from public,anon,authenticated;
create trigger supplier_mutation_guard before insert or update or delete on public.suppliers
  for each row execute function lt_security.audit_supplier_mutation();
create trigger supplier_mutation_audit after insert or update on public.suppliers
  for each row execute function lt_security.record_supplier_mutation();

-- Callers can read history but cannot fabricate, omit, rewrite or delete it.
revoke insert, update, delete on public.supplier_change_events from anon,authenticated;
revoke delete on public.suppliers from anon,authenticated;
